items=[]
for i,row in enumerate(rows.splitlines(),1):
 product,path,q,a,section=row.split('|')
 url=path if path.startswith('https:') else 'https://www.usaa.com/'+path
 items.append(dict(id=f'USAA-{i:03}',product=product,source_url=url,source_section=section,reviewed_on='2026-10-17',source_type='public_product_description',access_status='blocked_cookie_screen' if section=='Access blocked' else 'reviewed_public_page',question=q,reference_answer=a,expected_behavior='abstain_or_qualify' if a.startswith('No. The linked') or 'does not establish' in a or 'does not specify' in a or 'no dollar limit' in a else 'answer_with_conditions',must_check=['factual support','relevance','conditions and exclusions','citation accuracy','no unsupported personal coverage decision'],review_status='researcher_drafted_not_independently_adjudicated'))
# Each source paragraph paraphrase remains brief; no copied policy text.
out=Path('outputs'); out.mkdir(exist_ok=True)
(out/'usaa-evaluation-cases.json').write_text(json.dumps({'scope':'USAA public-information Q&A; not issued-policy coverage decisions','reviewed_on':'2026-10-17','cases':items},indent=2))
lines=['# USAA public-information research and evaluation seed set','', 'Reviewed October 17, 2026. These are public product pages, not complete issued policy contracts. Researcher-drafted reference answers need independent review before use as a formal benchmark. No model answers have been scored yet.','',f'## Scope: {len(items)} product categories','', 'All categories from the directory are represented, including annuities and phone protection, which should not automatically be treated as conventional insurance policies. The small-business navigation hub is not a separate product. Dental, vision and supplemental gap links share a health overview page. Aviation and workers compensation returned cookie screens even after trying the mobile site. Farm and ranch was readable on the mobile site.','', '## Proposed evaluation','', '1. Give the answering model the question and retrieved source context, without the reference answer.','2. Evaluate its response against the question, source context, and independently reviewed reference answer.','3. Judge factual support, completeness of relevant conditions, relevance, citation support, and abstention when evidence is missing.','4. Record separate labels and explanations in Phoenix; do not treat a successful export as a correct answer.','5. Include correct, contradictory, incomplete, wrong-product, and unanswerable cases. Calibrate a model judge against human labels.','', 'Do not give the evaluator only the retrieved passage: incomplete retrieval can hide a relevant exclusion. For policy decisions, retrieve the complete applicable contract context and version. Public pages alone cannot establish a specific insured person\'s limits, deductible, endorsements or claim eligibility.','', '## Inventory and reference questions','']
for x in items:
 lines += [f"### {x['id']} — {x['product']}",f"Source: [{x['source_section']}]({x['source_url']})",f"Status: {x['access_status']}",f"Question: {x['question']}",f"Expected answer: {x['reference_answer']}",'']
(out/'usaa-research-and-test-plan.md').write_text('\n'.join(lines))
print(f'Created {len(items)} reference cases; {sum(x["access_status"]=="blocked_cookie_screen" for x in items)} blocked categories.')
